package ratelimit

// TokenBucket implements a classic rate limiter using the token bucket
// algorithm. Tokens accrue at `rate` per second up to `capacity`; each
// request consumes one token. When the bucket is empty, requests are
// rejected (caller MUST back off or queue, not busy-wait).
//
// The bucket is NOT safe for concurrent use without external locking.
// Callers requiring goroutine-safe rate limiting SHOULD wrap Allow()
// in a mutex or swap to a channel-based implementation.
type TokenBucket struct {
	rate     float64
	capacity float64
	tokens   float64
	last     float64
	now      func() float64
}

func New(rate, capacity float64, now func() float64) *TokenBucket {
	return &TokenBucket{rate: rate, capacity: capacity, tokens: capacity, now: now}
}

// Allow returns true if a token is available, consuming it. Returns
// false when the bucket is empty — the caller SHOULD apply backpressure
// rather than retrying immediately, to avoid stampeding the downstream.
func (b *TokenBucket) Allow() bool {
	now := b.now()
	elapsed := now - b.last
	b.last = now

	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	if b.tokens < 1 {
		return false
	}
	b.tokens--
	return true
}

